export class Sound{
 constructor(){this.enabled=false;this.musicEnabled=true;this.started=false;}
 async activate(){try{if(!this.ctx){this.ctx=new AudioContext();this.master=this.ctx.createGain();this.master.gain.value=.16;const limiter=this.ctx.createDynamicsCompressor();limiter.threshold.value=-14;limiter.ratio.value=8;this.master.connect(limiter).connect(this.ctx.destination);this.engine=this.ctx.createOscillator();this.engine.type='sawtooth';this.engineGain=this.ctx.createGain();this.engineGain.gain.value=0;const filter=this.ctx.createBiquadFilter();filter.frequency.value=600;this.engine.connect(filter).connect(this.engineGain).connect(this.master);this.engine.start();}await this.ctx.resume();this.started=true;}catch{this.enabled=false;}}
 tone(freq,duration=.12,volume=.16){if(!this.ctx||!this.enabled)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g).connect(this.master);o.start();o.stop(t+duration);}
 update(car,active,scene,time){if(!this.ctx)return;this.engineGain.gain.setTargetAtTime(active&&this.enabled?.12:0,this.ctx.currentTime,.06);if(active&&car){this.engine.frequency.setTargetAtTime(45+Math.hypot(car.vx,car.vz)*4+(car.boosting?35:0),this.ctx.currentTime,.07);const beat=Math.floor(time*2);if(beat!==this.beat&&this.musicEnabled&&this.enabled){this.beat=beat;const notes={yard:[55,55,82.4,65.4],docks:[65.4,82.4,73.4,55],foundry:[49,58.3,73.4,58.3],final:[65.4,98,82.4,73.4]}[scene]||[55];this.tone(notes[beat%notes.length],.18,.06);}}}
 stop(){if(this.ctx)this.engineGain.gain.setTargetAtTime(0,this.ctx.currentTime,.02);}
}
